/**
 * `read_file`'s LINE WINDOW — the one place large-file pagination lives.
 *
 * Kept dependency-free on purpose: besides `core-tools.ts` (every TypeScript surface),
 * the Cloudflare Container imports a compiled copy (`api/container/fileWindow.mjs`,
 * generated by `api/scripts/gen-container-shared.mjs`), because that image has no build
 * step. Before that, the container's `read_file` ignored the advertised `offset`/`limit`
 * and returned the first 100K characters, so a model told to "call again with offset"
 * could never get past the head of a big file.
 */

/** Default line window for `read_file` — a large file returns a bounded slice the
 *  model pages through with `offset`/`limit`, instead of dumping (or failing) on it. */
export const READ_DEFAULT_LINE_LIMIT = 2000;

/** One window of a file, 1-based. */
export interface FileWindow {
  content: string;
  truncated: boolean;
  totalLines: number;
  offset: number;
  returnedLines: number;
}

/**
 * Window file content to a 1-based line range, reporting whether more remains. This
 * is the SINGLE place large-file pagination lives, so every surface (cloud, container,
 * on-prem, VS Code) behaves identically: `read_file` returns the requested slice plus a
 * `truncated` flag + a "read the next chunk" note when the file is longer than the
 * window. A provider only has to return the file's content (or its own truncated
 * chunk); the windowing math is here, once.
 */
export function windowFileContent(content: string, opts?: { offset?: number; limit?: number }): FileWindow {
  const lines = content.split("\n");
  const totalLines = lines.length;
  const start = opts?.offset && opts.offset > 1 ? Math.min(Math.floor(opts.offset), totalLines + 1) : 1;
  const limit = opts?.limit && opts.limit > 0 ? Math.floor(opts.limit) : READ_DEFAULT_LINE_LIMIT;
  const slice = lines.slice(start - 1, start - 1 + limit);
  const end = start - 1 + slice.length; // last line number included
  return { content: slice.join("\n"), truncated: end < totalLines, totalLines, offset: start, returnedLines: slice.length };
}

/** The "how to read the next chunk" note for a truncated window; `undefined` when the
 *  window reached the end of the file. */
export function fileWindowNote(win: FileWindow): string | undefined {
  if (!win.truncated) return undefined;
  const lastLine = win.offset + win.returnedLines - 1;
  return `Showing lines ${win.offset}–${lastLine} of ${win.totalLines}. To continue, call read_file again with offset ${lastLine + 1}.`;
}
